properties.query:
// detects suspicious usage of the legitimate tool bcedit
// The Bcdedit.exe command-line tool modifies the boot configuration data store. The boot configuration data store contains boot configuration parameters and controls how the operating system is booted.
let cmd_all = dynamic(["/set","recoveryenabled no"]);
let query1 = 
_Im_ProcessCreate(commandline_has_all=cmd_all,targetprocess_has_any="bcedit.exe");
let cmd_all2 = dynamic(["/set","bootstatuspolicy","ignoreallfailures"]);
let query2 = 
_Im_ProcessCreate(commandline_has_all=cmd_all2,targetprocess_has_any="bcedit.exe");
union isfuzzy = true
query1,query2
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
